Within @path and @<file> paths, Leo evaluates ``{{exp}}`` with the the following symbols defined: ``c``, ``g``, ``p``, ``os`` and ``sys``.  For example::

    @file {{os.path.abspath(os.curdir)}}/abc.py

refers to the file abc.py in (absolute path of) the current directory.

@language python

# To see this in action (from this file):
# - Ctrl-B to define the command.
# - Execute the i1 command

@g.command('i1')
def i1_command(event):
    c = event.get('c')
    if not c: return

    def callback(args, c, event):
        g.trace(args)
        c.bodyWantsFocus()

    c.interactive(callback, event, prompts=['Prompt: '])

